package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.zip.Zip64ExtendedInformationExtraField;
import org.apache.commons.compress.utils.ZipException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Zip64ExtendedInformationExtraField_reparseCentralDirectoryData_TriageGen1Test {

    private static final int DWORD = 8;
    private static final int WORD = 2;

    // Helper to inject rawCentralDirectoryData via reflection since it's likely private
    private void setRawData(Zip64ExtendedInformationExtraField field, byte[] data) throws Exception {
        Field dataField = Zip64ExtendedInformationExtraField.class.getDeclaredField("rawCentralDirectoryData");
        dataField.setAccessible(true);
        dataField.set(field, data);
    }

    @Test
    public void testReparse_NullData_DoesNothing() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        setRawData(field, null);
        // Should not throw exception even if params suggest data should exist
        field.reparseCentralDirectoryData(true, true, true, true);
    }

    @Test
    public void testReparse_AllTrue_Success() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // Expected: 8 + 8 + 8 + 2 = 26
        byte[] data = new byte[26];
        for (int i = 0; i < 26; i++) data[i] = (byte) i;
        setRawData(field, data);

        field.reparseCentralDirectoryData(true, true, true, true);

        Assert.assertNotNull(field.getSize());
        Assert.assertNotNull(field.getCompressedSize());
        Assert.assertNotNull(field.getRelativeHeaderOffset());
        Assert.assertNotNull(field.getDiskStartNumber());
    }

    @Test
    public void testReparse_AllFalse_Success() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] data = new byte[0];
        setRawData(field, data);

        field.reparseCentralDirectoryData(false, false, false, false);

        Assert.assertNull(field.getSize());
        Assert.assertNull(field.getCompressedSize());
        Assert.assertNull(field.getRelativeHeaderOffset());
        Assert.assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testReparse_PartialTrue_Success_Case1() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // true, false, true, false => 8 + 0 + 8 + 0 = 16
        byte[] data = new byte[16];
        setRawData(field, data);

        field.reparseCentralDirectoryData(true, false, true, false);

        Assert.assertNotNull(field.getSize());
        Assert.assertNull(field.getCompressedSize());
        Assert.assertNotNull(field.getRelativeHeaderOffset());
        Assert.assertNull(field.getDiskStartNumber());
    }

    @Test
    public void testReparse_PartialTrue_Success_Case2() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // false, false, false, true => 0 + 0 + 0 + 2 = 2
        byte[] data = new byte[2];
        setRawData(field, data);

        field.reparseCentralDirectoryData(false, false, false, true);

        Assert.assertNull(field.getSize());
        Assert.assertNull(field.getCompressedSize());
        Assert.assertNull(field.getRelativeHeaderOffset());
        Assert.assertNotNull(field.getDiskStartNumber());
    }

    @Test(expected = ZipException.class)
    public void testReparse_WrongLength_ThrowsException() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        // Expected: 8 (uncompressed) + 8 (compressed) = 16
        // Providing 10
        byte[] data = new byte[10];
        setRawData(field, data);

        field.reparseCentralDirectoryData(true, true, false, false);
    }

    @Test
    public void testReparse_SingleField_UncompressedSize() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] data = new byte[8];
        data[0] = 0x01;
        setRawData(field, data);

        field.reparseCentralDirectoryData(true, false, false, false);
        Assert.assertNotNull(field.getSize());
    }

    @Test
    public void testReparse_SingleField_CompressedSize() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] data = new byte[8];
        data[0] = 0x01;
        setRawData(field, data);

        field.reparseCentralDirectoryData(false, true, false, false);
        Assert.assertNotNull(field.getCompressedSize());
    }

    @Test
    public void testReparse_SingleField_RelativeHeaderOffset() throws Exception {
        Zip64ExtendedInformationExtraField field = new Zip64ExtendedInformationExtraField();
        byte[] data = new byte[8];
        data[0] = 0x01;
        setRawData(field, data);

        field.reparseCentralDirectoryData(false, false, true, false);
        Assert.assertNotNull(field.getRelativeHeaderOffset());
    }
}
